func (c *AppSecClient) UploadReport(ctx context.Context, body *AppSecReportUploadForm, opts *AppSecUploadReportOptions) (*Response, error) {
	if body == nil {
		err := fmt.Errorf("sourcecraft: body is required for AppSec UploadReport")
		return nil, err
	}
	path, err := expandPath("/v1/reports/upload")
	if err != nil {
		return nil, err
	}
	fields := []formField{}
	if strings.TrimSpace(string(body.Commit)) == "" {
		return nil, fmt.Errorf("sourcecraft: multipart field commit is required")
	}
	fields = append(fields, formField{"commit", string(body.Commit)})
	if strings.TrimSpace(string(body.EngineName)) == "" {
		return nil, fmt.Errorf("sourcecraft: multipart field engineName is required")
	}
	fields = append(fields, formField{"engineName", string(body.EngineName)})
	if body.EngineType != nil {
		fields = append(fields, formField{"engineType", string(*body.EngineType)})
	}
	if body.ExpectedReportCount != nil {
		fields = append(fields, formField{"expectedReportCount", strconv.FormatInt(int64(*body.ExpectedReportCount), 10)})
	}
	if body.IsReactive != nil {
		fields = append(fields, formField{"isReactive", strconv.FormatBool(*body.IsReactive)})
	}
	if body.PRUUID != nil {
		fields = append(fields, formField{"prUuid", string(*body.PRUUID)})
	}
	if body.Reactive != nil {
		fields = append(fields, formField{"reactive", strconv.FormatBool(*body.Reactive)})
	}
	if strings.TrimSpace(string(body.ReportType)) == "" {
		return nil, fmt.Errorf("sourcecraft: multipart field reportType is required")
	}
	fields = append(fields, formField{"reportType", string(body.ReportType)})
	if body.ScanBasePathAbsolute != nil {
		fields = append(fields, formField{"scanBasePathAbsolute", string(*body.ScanBasePathAbsolute)})
	}
	if body.ScanTime != nil {
		fields = append(fields, formField{"scanTime", strconv.FormatInt(int64(*body.ScanTime), 10)})
	}
	if body.ScanUUID != nil {
		fields = append(fields, formField{"scanUuid", string(*body.ScanUUID)})
	}
	if body.ShouldTriggerEnrichment != nil {
		fields = append(fields, formField{"shouldTriggerEnrichment", strconv.FormatBool(*body.ShouldTriggerEnrichment)})
	}
	return c.uploadReport(ctx, path, opts, body.File, fields)
}

