func (c *AppSecClient) GetScan(ctx context.Context, scanUUID string, opts *AppSecGetScanOptions) (*AppSecScanDetailsDTO, *Response, error) {
	path, err := expandPath("/v1/scans/{scanUuid}", pathParam{"scanUuid", scanUUID})
	if err != nil {
		return nil, nil, err
	}
	return doJSON[AppSecScanDetailsDTO](ctx, c.transport(), "GET", path, opts, nil)
}
